QUESTIONS.push(
{"id": "DL1-001", "lecture": "DL1", "prof": "Gottlieb", "tier": "new", "topic": "DL1", "skill": "drug", "source": "slide", "cite": "Exam_1_Drug_List_2026.pdf, Table 1", "sub": "adr", "concept": "moa-norepinephrine", "tags": ["drug-list"], "stem": "Which of the following describes the mechanism of action of norepinephrine?", "options": [{"t": "α1, α2, β1 and β2 agonist", "correct": true, "why": "Norepinephrine is listed as α1, α2, β1 and β2 agonist."}, {"t": "α1 agonist", "correct": false, "why": "That is phenylephrine; norepinephrine is listed as α1, α2, β1 and β2 agonist."}, {"t": "β1 and β2 partial agonist", "correct": false, "why": "That is pindolol; norepinephrine is listed as α1, α2, β1 and β2 agonist."}, {"t": "α1 and α2 antagonist, irreversible", "correct": false, "why": "That is phenoxybenzamine; norepinephrine is listed as α1, α2, β1 and β2 agonist."}], "teach": "Norepinephrine activates all four adrenoceptors on the list (α1, α2, β1, β2). Phenylephrine activates α1 alone.", "reading": [{"src": "Katzung 16e, Ch. 2", "sec": "Receptors mediate the actions of agonists and antagonists", "t": "An agonist binds the receptor and activates it, so the receptor signals as a direct result of the binding."}, {"src": "Katzung 16e, Ch. 6", "sec": "Autonomic Receptors, Table 6-2", "t": "Ligand binding at α1 forms IP3 and DAG and raises calcium (smooth muscle contracts); at α2 it lowers cAMP; at β1 and β2 it raises cAMP (heart speeds up, bronchiolar smooth muscle relaxes)."}]},
{"id": "DL1-002", "lecture": "DL1", "prof": "Gottlieb", "tier": "new", "topic": "DL1", "skill": "drug", "source": "slide", "cite": "Exam_1_Drug_List_2026.pdf, Table 1", "sub": "adr", "concept": "moa-epinephrine", "tags": ["drug-list"], "stem": "Which of the following describes the mechanism of action of epinephrine?", "options": [{"t": "α1, α2, β1 and β2 agonist", "correct": true, "why": "Epinephrine is listed as α1, α2, β1 and β2 agonist."}, {"t": "β2 partial agonist", "correct": false, "why": "That is albuterol; epinephrine is listed as α1, α2, β1 and β2 agonist."}, {"t": "α1 agonist", "correct": false, "why": "That is phenylephrine; epinephrine is listed as α1, α2, β1 and β2 agonist."}, {"t": "α1 and α2 antagonist, irreversible", "correct": false, "why": "That is phenoxybenzamine; epinephrine is listed as α1, α2, β1 and β2 agonist."}], "teach": "Epinephrine, like norepinephrine, activates α1, α2, β1 and β2. The selective drugs on the list act at one or two of these.", "reading": [{"src": "Katzung 16e, Ch. 2", "sec": "Receptors mediate the actions of agonists and antagonists", "t": "An agonist binds the receptor and activates it, so the receptor signals as a direct result of the binding."}, {"src": "Katzung 16e, Ch. 6", "sec": "Autonomic Receptors, Table 6-2", "t": "Ligand binding at α1 forms IP3 and DAG and raises calcium (smooth muscle contracts); at α2 it lowers cAMP; at β1 and β2 it raises cAMP (heart speeds up, bronchiolar smooth muscle relaxes)."}]},
{"id": "DL1-003", "lecture": "DL1", "prof": "Gottlieb", "tier": "new", "topic": "DL1", "skill": "drug", "source": "slide", "cite": "Exam_1_Drug_List_2026.pdf, Table 1", "sub": "chol", "concept": "moa-acetylcholine", "tags": ["drug-list"], "stem": "Acetylcholine is an agonist at which receptors?", "options": [{"t": "M1, M2, M3, Nn and Nm", "correct": true, "why": "Acetylcholine activates both receptor families: muscarinic (M1, M2, M3) and nicotinic (Nn, Nm)."}, {"t": "M1, M2 and M3 only", "correct": false, "why": "Leaves out the nicotinic receptors; M1, M2 and M3 alone are the receptors tropicamide blocks."}, {"t": "Nn only", "correct": false, "why": "Nn alone is where varenicline is a partial agonist; acetylcholine acts at all five listed receptors."}, {"t": "Nn and Nm only", "correct": false, "why": "Leaves out the muscarinic receptors M1, M2 and M3."}, {"t": "M1, M2, M3, Nn, Nm, H1 and H2", "correct": false, "why": "H1 and H2 are histamine receptors, listed for histamine, not acetylcholine."}], "teach": "Acetylcholine activates both cholinergic receptor families: muscarinic (M1, M2, M3) and nicotinic (Nn, Nm). Tropicamide blocks the muscarinic ones; varenicline partially activates Nn.", "reading": [{"src": "Katzung 16e, Ch. 6", "sec": "Autonomic Receptors, Table 6-2", "t": "Muscarinic M1 and M3 signal through IP3, DAG and calcium and M2 opens potassium channels; nicotinic Nn and Nm are ligand-gated channels that open sodium and potassium channels and depolarize the cell."}]},
{"id": "DL1-004", "lecture": "DL1", "prof": "Gottlieb", "tier": "new", "topic": "DL1", "skill": "drug", "source": "slide", "cite": "Exam_1_Drug_List_2026.pdf, Table 1", "sub": "chol", "concept": "moa-tropicamide", "tags": ["drug-list"], "stem": "Which of the following describes the mechanism of action of tropicamide?", "options": [{"t": "Muscarinic (M1, M2, M3) antagonist, reversible", "correct": true, "why": "Tropicamide is listed as muscarinic (M1, M2, M3) antagonist, reversible."}, {"t": "Muscarinic (M1, M2, M3) and nicotinic (Nn, Nm) agonist", "correct": false, "why": "That is acetylcholine; tropicamide is listed as muscarinic (M1, M2, M3) antagonist, reversible."}, {"t": "Nicotinic (Nn) partial agonist", "correct": false, "why": "That is varenicline; tropicamide is listed as muscarinic (M1, M2, M3) antagonist, reversible."}, {"t": "Non-selective histamine receptor antagonist", "correct": false, "why": "That is diphenhydramine; tropicamide is listed as muscarinic (M1, M2, M3) antagonist, reversible."}], "teach": "Tropicamide binds M1, M2 and M3 without activating them and blocks acetylcholine there; the block is reversible.", "reading": [{"src": "Katzung 16e, Ch. 2", "sec": "Competitive & Irreversible Antagonists", "t": "A reversible (competitive) antagonist binds the receptor without activating it and blocks the agonist; enough agonist can surmount the block, so the agonist curve shifts right with the same maximum."}, {"src": "Katzung 16e, Ch. 6", "sec": "Autonomic Receptors, Table 6-2", "t": "M1 and M3 receptors signal through IP3, DAG and calcium; M2 receptors open potassium channels and inhibit adenylyl cyclase (myocardium)."}]},
{"id": "DL1-005", "lecture": "DL1", "prof": "Gottlieb", "tier": "new", "topic": "DL1", "skill": "drug", "source": "slide", "cite": "Exam_1_Drug_List_2026.pdf, Table 1", "sub": "adr", "concept": "moa-prazosin", "tags": ["drug-list"], "stem": "Which of the following describes the mechanism of action of prazosin?", "options": [{"t": "α1 antagonist, reversible", "correct": true, "why": "Prazosin is listed as α1 antagonist, reversible."}, {"t": "α1 agonist", "correct": false, "why": "That is phenylephrine; prazosin is listed as α1 antagonist, reversible."}, {"t": "α1 and α2 antagonist, irreversible", "correct": false, "why": "That is phenoxybenzamine; prazosin is listed as α1 antagonist, reversible."}, {"t": "β1 antagonist, reversible", "correct": false, "why": "That is metoprolol; prazosin is listed as α1 antagonist, reversible."}], "teach": "Prazosin binds α1 without activating it and blocks agonists there reversibly. Phenoxybenzamine also blocks α1, but irreversibly and at α2 too.", "reading": [{"src": "Katzung 16e, Ch. 2", "sec": "Competitive & Irreversible Antagonists", "t": "A reversible (competitive) antagonist binds the receptor without activating it and blocks the agonist; enough agonist can surmount the block, so the agonist curve shifts right with the same maximum."}, {"src": "Katzung 16e, Ch. 6", "sec": "Autonomic Receptors, Table 6-2", "t": "α1 receptors sit on effector cells, especially smooth muscle; ligand binding forms IP3 and DAG and raises intracellular calcium, which contracts the muscle."}], "fg": "classes"},
{"id": "DL1-006", "lecture": "DL1", "prof": "Gottlieb", "tier": "new", "topic": "DL1", "skill": "drug", "source": "slide", "cite": "Exam_1_Drug_List_2026.pdf, Table 1", "sub": "adr", "concept": "moa-phenylephrine", "tags": ["drug-list"], "stem": "Which of the following describes the mechanism of action of phenylephrine?", "options": [{"t": "α1 agonist", "correct": true, "why": "Phenylephrine is listed as α1 agonist."}, {"t": "α1 antagonist, reversible", "correct": false, "why": "That is prazosin; phenylephrine is listed as α1 agonist."}, {"t": "α1, α2, β1 and β2 agonist", "correct": false, "why": "That is norepinephrine and epinephrine; phenylephrine is listed as α1 agonist."}, {"t": "β2 partial agonist", "correct": false, "why": "That is albuterol; phenylephrine is listed as α1 agonist."}], "teach": "Phenylephrine binds α1 and activates it; it does not act at α2 or β receptors. Prazosin binds the same receptor and blocks it.", "reading": [{"src": "Katzung 16e, Ch. 2", "sec": "Receptors mediate the actions of agonists and antagonists", "t": "An agonist binds the receptor and activates it, so the receptor signals as a direct result of the binding."}, {"src": "Katzung 16e, Ch. 6", "sec": "Autonomic Receptors, Table 6-2", "t": "α1 receptors sit on effector cells, especially smooth muscle; ligand binding forms IP3 and DAG and raises intracellular calcium, which contracts the muscle."}], "fg": "classes"},
{"id": "DL1-007", "lecture": "DL1", "prof": "Gottlieb", "tier": "new", "topic": "DL1", "skill": "drug", "source": "slide", "cite": "Exam_1_Drug_List_2026.pdf, Table 1", "sub": "adr", "concept": "moa-phenoxybenzamine", "tags": ["drug-list"], "stem": "Which of the following describes the mechanism of action of phenoxybenzamine?", "options": [{"t": "α1 and α2 antagonist, irreversible", "correct": true, "why": "Phenoxybenzamine is listed as α1 and α2 antagonist, irreversible."}, {"t": "α1 antagonist, reversible", "correct": false, "why": "That is prazosin; phenoxybenzamine is listed as α1 and α2 antagonist, irreversible."}, {"t": "β1 and β2 partial agonist", "correct": false, "why": "That is pindolol; phenoxybenzamine is listed as α1 and α2 antagonist, irreversible."}, {"t": "Muscarinic (M1, M2, M3) antagonist, reversible", "correct": false, "why": "That is tropicamide; phenoxybenzamine is listed as α1 and α2 antagonist, irreversible."}], "teach": "Phenoxybenzamine binds α1 and α2 irreversibly, so the block cannot be overcome by more agonist. It is the only irreversible drug on the list; every other drug is reversible and competitive.", "reading": [{"src": "Katzung 16e, Ch. 2", "sec": "Competitive & Irreversible Antagonists", "t": "An irreversible antagonist binds the receptor irreversibly (sometimes covalently), so no agonist concentration can surmount the block and the maximal agonist effect falls; the block lasts until new receptors are made."}, {"src": "Katzung 16e, Ch. 6", "sec": "Autonomic Receptors, Table 6-2", "t": "α1 binding forms IP3 and DAG and raises calcium, contracting smooth muscle; α2 binding inhibits adenylyl cyclase and lowers cAMP."}], "fg": "classes"},
{"id": "DL1-008", "lecture": "DL1", "prof": "Gottlieb", "tier": "new", "topic": "DL1", "skill": "drug", "source": "slide", "cite": "Exam_1_Drug_List_2026.pdf, Table 1", "sub": "adr", "concept": "moa-metoprolol", "tags": ["drug-list"], "stem": "Which of the following describes the mechanism of action of metoprolol?", "options": [{"t": "β1 antagonist, reversible", "correct": true, "why": "Metoprolol is listed as β1 antagonist, reversible."}, {"t": "β1 and β2 partial agonist", "correct": false, "why": "That is pindolol; metoprolol is listed as β1 antagonist, reversible."}, {"t": "α1 antagonist, reversible", "correct": false, "why": "That is prazosin; metoprolol is listed as β1 antagonist, reversible."}, {"t": "α1 and α2 antagonist, irreversible", "correct": false, "why": "That is phenoxybenzamine; metoprolol is listed as β1 antagonist, reversible."}], "teach": "Metoprolol binds β1 without activating it and blocks agonists there reversibly. Pindolol acts at β1 too, but as a partial agonist and at β2 as well.", "reading": [{"src": "Katzung 16e, Ch. 2", "sec": "Competitive & Irreversible Antagonists", "t": "A reversible (competitive) antagonist binds the receptor without activating it and blocks the agonist; enough agonist can surmount the block, so the agonist curve shifts right with the same maximum."}, {"src": "Katzung 16e, Ch. 6", "sec": "Autonomic Receptors, Table 6-2", "t": "β1 receptors sit especially on the heart; ligand binding stimulates adenylyl cyclase and raises cAMP, which speeds the sinoatrial node and increases contractility."}]},
{"id": "DL1-009", "lecture": "DL1", "prof": "Gottlieb", "tier": "new", "topic": "DL1", "skill": "drug", "source": "slide", "cite": "Exam_1_Drug_List_2026.pdf, Table 1", "sub": "gaba", "concept": "moa-diazepam", "tags": ["drug-list"], "stem": "Which of the following describes the mechanism of action of diazepam?", "options": [{"t": "GABA receptor allosteric agonist", "correct": true, "why": "Diazepam is listed as GABA receptor allosteric agonist."}, {"t": "Histamine H1 inverse agonist", "correct": false, "why": "That is loratadine; diazepam is listed as GABA receptor allosteric agonist."}, {"t": "Nicotinic (Nn) partial agonist", "correct": false, "why": "That is varenicline; diazepam is listed as GABA receptor allosteric agonist."}, {"t": "Non-selective histamine receptor antagonist", "correct": false, "why": "That is diphenhydramine; diazepam is listed as GABA receptor allosteric agonist."}], "teach": "Diazepam does not bind where GABA binds. It binds a second site on the same GABA receptor, and while it sits there the receptor responds more strongly to GABA. Alone it does little; with GABA present it makes GABA work better.", "reading": [{"src": "Katzung 16e, Ch. 2", "sec": "Competitive & Irreversible Antagonists — allosteric modulators", "t": "Diazepam and the other benzodiazepines bind an allosteric site, not the site GABA binds, and increase the channel opening that GABA produces; on their own they have little effect."}, {"src": "Katzung 16e, Ch. 2", "sec": "Competitive & Irreversible Antagonists — allosteric modulators", "t": "The GABA receptor is an ion channel that the neurotransmitter GABA opens."}], "note": "Two names for one mechanism. The Exam 1 drug list calls diazepam a GABA receptor allosteric agonist. Katzung Ch. 2 calls it a positive allosteric modulator: it binds a second site on the receptor, does little by itself, and makes the receptor respond more strongly to GABA. On the exam, use the drug list’s name.", "fg": "classes"},
{"id": "DL1-010", "lecture": "DL1", "prof": "Gottlieb", "tier": "new", "topic": "DL1", "skill": "drug", "source": "slide", "cite": "Exam_1_Drug_List_2026.pdf, Table 1", "sub": "adr", "concept": "moa-albuterol", "tags": ["drug-list"], "stem": "Which of the following describes the mechanism of action of albuterol?", "options": [{"t": "β2 partial agonist", "correct": true, "why": "Albuterol is listed as β2 partial agonist."}, {"t": "β1 and β2 partial agonist", "correct": false, "why": "That is pindolol; albuterol is listed as β2 partial agonist."}, {"t": "β1 antagonist, reversible", "correct": false, "why": "That is metoprolol; albuterol is listed as β2 partial agonist."}, {"t": "α1, α2, β1 and β2 agonist", "correct": false, "why": "That is norepinephrine and epinephrine; albuterol is listed as β2 partial agonist."}], "teach": "Albuterol activates β2 but reaches a lower maximal response than a full agonist would. It does not act at β1; pindolol is the partial agonist that does.", "reading": [{"src": "Katzung 16e, Ch. 2", "sec": "Partial Agonists", "t": "A partial agonist activates the receptor but produces a lower maximal response at full receptor occupancy than a full agonist does, and it competes with a full agonist for the same sites."}, {"src": "Katzung 16e, Ch. 6", "sec": "Autonomic Receptors, Table 6-2", "t": "β2 receptors sit especially on smooth muscle; ligand binding stimulates adenylyl cyclase and raises cAMP, which relaxes bronchiolar smooth muscle."}]},
{"id": "DL1-011", "lecture": "DL1", "prof": "Gottlieb", "tier": "new", "topic": "DL1", "skill": "drug", "source": "slide", "cite": "Exam_1_Drug_List_2026.pdf, Table 1", "sub": "chol", "concept": "moa-varenicline", "tags": ["drug-list"], "stem": "Which of the following describes the mechanism of action of varenicline?", "options": [{"t": "Nicotinic (Nn) partial agonist", "correct": true, "why": "Varenicline is listed as nicotinic (Nn) partial agonist."}, {"t": "Muscarinic (M1, M2, M3) and nicotinic (Nn, Nm) agonist", "correct": false, "why": "That is acetylcholine; varenicline is listed as nicotinic (Nn) partial agonist."}, {"t": "Muscarinic (M1, M2, M3) antagonist, reversible", "correct": false, "why": "That is tropicamide; varenicline is listed as nicotinic (Nn) partial agonist."}, {"t": "β2 partial agonist", "correct": false, "why": "That is albuterol; varenicline is listed as nicotinic (Nn) partial agonist."}], "teach": "Varenicline activates the neuronal nicotinic receptor Nn, but only to a submaximal response. Acetylcholine is the full agonist at Nn and at the other cholinergic receptors.", "reading": [{"src": "Katzung 16e, Ch. 2", "sec": "Partial Agonists", "t": "A partial agonist activates the receptor but produces a lower maximal response at full receptor occupancy than a full agonist does, and it competes with a full agonist for the same sites."}, {"src": "Katzung 16e, Ch. 6", "sec": "Autonomic Receptors, Table 6-2", "t": "The Nn receptor on postganglionic neurons is a ligand-gated channel: binding opens sodium and potassium channels and depolarizes the neuron."}]},
{"id": "DL1-012", "lecture": "DL1", "prof": "Gottlieb", "tier": "new", "topic": "DL1", "skill": "drug", "source": "slide", "cite": "Exam_1_Drug_List_2026.pdf, Table 1", "sub": "hist", "concept": "moa-histamine", "tags": ["drug-list"], "stem": "Which of the following describes the mechanism of action of histamine?", "options": [{"t": "Histamine H1 and H2 agonist", "correct": true, "why": "Histamine is listed as histamine H1 and H2 agonist."}, {"t": "Histamine H1 inverse agonist", "correct": false, "why": "That is loratadine; histamine is listed as histamine H1 and H2 agonist."}, {"t": "Non-selective histamine receptor antagonist", "correct": false, "why": "That is diphenhydramine; histamine is listed as histamine H1 and H2 agonist."}, {"t": "GABA receptor allosteric agonist", "correct": false, "why": "That is diazepam; histamine is listed as histamine H1 and H2 agonist."}], "teach": "Histamine activates both H1 and H2. Loratadine and diphenhydramine oppose it: loratadine as an H1 inverse agonist, diphenhydramine as a non-selective antagonist.", "reading": [{"src": "Katzung 16e, Ch. 2", "sec": "Receptors mediate the actions of agonists and antagonists", "t": "An agonist binds the receptor and activates it, so the receptor signals as a direct result of the binding."}, {"src": "Katzung 16e, Ch. 2", "sec": "Receptor Classes & Drug Development", "t": "Histamine activates more than one receptor subtype, and each subtype can couple to a different G protein, which is what lets a drug be selective for one subtype."}]},
{"id": "DL1-013", "lecture": "DL1", "prof": "Gottlieb", "tier": "new", "topic": "DL1", "skill": "drug", "source": "slide", "cite": "Exam_1_Drug_List_2026.pdf, Table 1", "sub": "hist", "concept": "moa-loratadine", "tags": ["drug-list"], "stem": "Which of the following describes the mechanism of action of loratadine?", "options": [{"t": "Histamine H1 inverse agonist", "correct": true, "why": "Loratadine is listed as histamine H1 inverse agonist."}, {"t": "Non-selective histamine receptor antagonist", "correct": false, "why": "That is diphenhydramine; loratadine is listed as histamine H1 inverse agonist."}, {"t": "Histamine H1 and H2 agonist", "correct": false, "why": "That is histamine; loratadine is listed as histamine H1 inverse agonist."}, {"t": "Muscarinic (M1, M2, M3) antagonist, reversible", "correct": false, "why": "That is tropicamide; loratadine is listed as histamine H1 inverse agonist."}], "teach": "Loratadine binds H1 and lowers its activity below baseline (inverse agonist). Diphenhydramine blocks histamine receptors without selectivity.", "reading": [{"src": "Katzung 16e, Ch. 2", "sec": "Competitive & Irreversible Antagonists", "t": "An inverse agonist binds the receptor and lowers its activity below the basal level seen with no agonist present, rather than merely blocking the agonist."}, {"src": "Katzung 16e, Ch. 2", "sec": "Receptor Classes & Drug Development", "t": "Histamine activates more than one receptor subtype, and each subtype can couple to a different G protein, which is what lets a drug be selective for one subtype."}]},
{"id": "DL1-014", "lecture": "DL1", "prof": "Gottlieb", "tier": "new", "topic": "DL1", "skill": "drug", "source": "slide", "cite": "Exam_1_Drug_List_2026.pdf, Table 1", "sub": "adr", "concept": "moa-pindolol", "tags": ["drug-list"], "stem": "Which of the following describes the mechanism of action of pindolol?", "options": [{"t": "β1 and β2 partial agonist", "correct": true, "why": "Pindolol is listed as β1 and β2 partial agonist."}, {"t": "β1 antagonist, reversible", "correct": false, "why": "That is metoprolol; pindolol is listed as β1 and β2 partial agonist."}, {"t": "β2 partial agonist", "correct": false, "why": "That is albuterol; pindolol is listed as β1 and β2 partial agonist."}, {"t": "α1 and α2 antagonist, irreversible", "correct": false, "why": "That is phenoxybenzamine; pindolol is listed as β1 and β2 partial agonist."}], "teach": "Pindolol activates β1 and β2, but only to a submaximal response, so it is a partial agonist. Metoprolol blocks β1 outright; albuterol is partial at β2 only.", "reading": [{"src": "Katzung 16e, Ch. 2", "sec": "Partial Agonists", "t": "A partial agonist activates the receptor but produces a lower maximal response at full receptor occupancy than a full agonist does, and it competes with a full agonist for the same sites."}, {"src": "Katzung 16e, Ch. 6", "sec": "Autonomic Receptors, Table 6-2", "t": "β1 (heart) and β2 (smooth muscle) both raise cAMP through adenylyl cyclase: β1 speeds the sinoatrial node and increases contractility, β2 relaxes bronchiolar smooth muscle."}]},
{"id": "DL1-015", "lecture": "DL1", "prof": "Gottlieb", "tier": "new", "topic": "DL1", "skill": "drug", "source": "slide", "cite": "Exam_1_Drug_List_2026.pdf, Table 1", "sub": "hist", "concept": "moa-diphenhydramine", "tags": ["drug-list"], "stem": "Which of the following describes the mechanism of action of diphenhydramine?", "options": [{"t": "Non-selective histamine receptor antagonist", "correct": true, "why": "Diphenhydramine is listed as non-selective histamine receptor antagonist."}, {"t": "Histamine H1 inverse agonist", "correct": false, "why": "That is loratadine; diphenhydramine is listed as non-selective histamine receptor antagonist."}, {"t": "Histamine H1 and H2 agonist", "correct": false, "why": "That is histamine; diphenhydramine is listed as non-selective histamine receptor antagonist."}, {"t": "Muscarinic (M1, M2, M3) antagonist, reversible", "correct": false, "why": "That is tropicamide; diphenhydramine is listed as non-selective histamine receptor antagonist."}], "teach": "Diphenhydramine binds histamine receptors without activating them and without selecting one subtype. Loratadine is selective for H1 and is an inverse agonist.", "reading": [{"src": "Katzung 16e, Ch. 2", "sec": "Competitive & Irreversible Antagonists", "t": "A reversible (competitive) antagonist binds the receptor without activating it and blocks the agonist; enough agonist can surmount the block, so the agonist curve shifts right with the same maximum."}, {"src": "Katzung 16e, Ch. 2", "sec": "Receptor Classes & Drug Development", "t": "Histamine activates more than one receptor subtype, and each subtype can couple to a different G protein, which is what lets a drug be selective for one subtype."}]},
{"id": "DL1-016", "lecture": "DL1", "prof": "Gottlieb", "tier": "new", "topic": "DL1", "skill": "drug", "source": "slide", "cite": "Exam_1_Drug_List_2026.pdf, Table 1", "sub": "adr", "concept": "irreversible-drug", "tags": ["drug-list"], "stem": "Phenoxybenzamine differs from every other drug on the Exam 1 list in which way?", "options": [{"t": "It binds its receptors irreversibly", "correct": true, "why": "The list states all its drugs are reversible and competitive at their receptors, with one exception: phenoxybenzamine, which is irreversible."}, {"t": "It is a partial agonist at β receptors", "correct": false, "why": "That describes pindolol (β1 and β2) and albuterol (β2)."}, {"t": "It is selective for the α1 receptor", "correct": false, "why": "Phenoxybenzamine blocks α1 and α2. The α1-selective drugs on the list are prazosin (antagonist) and phenylephrine (agonist)."}, {"t": "It acts at an allosteric site on its receptor", "correct": false, "why": "The list gives an allosteric mechanism only for diazepam at the GABA receptor."}], "teach": "Phenoxybenzamine binds α1 and α2 irreversibly, so the block cannot be overcome by more agonist. It is the only irreversible drug on the list; every other drug is reversible and competitive.", "reading": [{"src": "Katzung 16e, Ch. 2", "sec": "Competitive & Irreversible Antagonists", "t": "An irreversible antagonist binds the receptor irreversibly (sometimes covalently), so no agonist concentration can surmount the block and the maximal agonist effect falls; the block lasts until new receptors are made."}], "fg": "classes"},
{"id": "DL1-017", "lecture": "DL1", "prof": "Gottlieb", "tier": "new", "topic": "DL1", "skill": "drug", "source": "slide", "cite": "Exam_1_Drug_List_2026.pdf, Table 1", "sub": "hist", "concept": "moa-loratadine", "tags": ["drug-list"], "stem": "Which drug is a histamine H1 receptor inverse agonist?", "options": [{"t": "Loratadine", "correct": true, "why": "Loratadine is listed as histamine H1 inverse agonist."}, {"t": "Diphenhydramine", "correct": false, "why": "Diphenhydramine is listed as non-selective histamine receptor antagonist."}, {"t": "Histamine", "correct": false, "why": "Histamine is listed as histamine H1 and H2 agonist."}, {"t": "Tropicamide", "correct": false, "why": "Tropicamide is listed as muscarinic (M1, M2, M3) antagonist, reversible."}, {"t": "Diazepam", "correct": false, "why": "Diazepam is listed as GABA receptor allosteric agonist."}], "teach": "Loratadine binds H1 and lowers its activity below baseline (inverse agonist). Diphenhydramine blocks histamine receptors without selectivity.", "reading": [{"src": "Katzung 16e, Ch. 2", "sec": "Competitive & Irreversible Antagonists", "t": "An inverse agonist binds the receptor and lowers its activity below the basal level seen with no agonist present, rather than merely blocking the agonist."}, {"src": "Katzung 16e, Ch. 2", "sec": "Receptor Classes & Drug Development", "t": "Histamine activates more than one receptor subtype, and each subtype can couple to a different G protein, which is what lets a drug be selective for one subtype."}]},
{"id": "DL1-018", "lecture": "DL1", "prof": "Gottlieb", "tier": "new", "topic": "DL1", "skill": "drug", "source": "slide", "cite": "Exam_1_Drug_List_2026.pdf, Table 1", "sub": "chol", "concept": "moa-varenicline", "tags": ["drug-list"], "stem": "Which drug is a partial agonist at the neuronal nicotinic (Nn) receptor?", "options": [{"t": "Varenicline", "correct": true, "why": "Varenicline is listed as nicotinic (Nn) partial agonist."}, {"t": "Acetylcholine", "correct": false, "why": "Acetylcholine is listed as muscarinic (M1, M2, M3) and nicotinic (Nn, Nm) agonist."}, {"t": "Tropicamide", "correct": false, "why": "Tropicamide is listed as muscarinic (M1, M2, M3) antagonist, reversible."}, {"t": "Albuterol", "correct": false, "why": "Albuterol is listed as β2 partial agonist."}, {"t": "Pindolol", "correct": false, "why": "Pindolol is listed as β1 and β2 partial agonist."}], "teach": "Varenicline activates the neuronal nicotinic receptor Nn, but only to a submaximal response. Acetylcholine is the full agonist at Nn and at the other cholinergic receptors.", "reading": [{"src": "Katzung 16e, Ch. 2", "sec": "Partial Agonists", "t": "A partial agonist activates the receptor but produces a lower maximal response at full receptor occupancy than a full agonist does, and it competes with a full agonist for the same sites."}, {"src": "Katzung 16e, Ch. 6", "sec": "Autonomic Receptors, Table 6-2", "t": "The Nn receptor on postganglionic neurons is a ligand-gated channel: binding opens sodium and potassium channels and depolarizes the neuron."}]},
{"id": "DL1-019", "lecture": "DL1", "prof": "Gottlieb", "tier": "new", "topic": "DL1", "skill": "drug", "source": "slide", "cite": "Exam_1_Drug_List_2026.pdf, Table 1", "sub": "adr", "concept": "moa-phenylephrine", "tags": ["drug-list"], "stem": "Which drug is a selective α1 agonist?", "options": [{"t": "Phenylephrine", "correct": true, "why": "Phenylephrine is listed as α1 agonist."}, {"t": "Prazosin", "correct": false, "why": "Prazosin is listed as α1 antagonist, reversible."}, {"t": "Norepinephrine", "correct": false, "why": "Norepinephrine is listed as α1, α2, β1 and β2 agonist."}, {"t": "Phenoxybenzamine", "correct": false, "why": "Phenoxybenzamine is listed as α1 and α2 antagonist, irreversible."}, {"t": "Albuterol", "correct": false, "why": "Albuterol is listed as β2 partial agonist."}], "teach": "Phenylephrine binds α1 and activates it; it does not act at α2 or β receptors. Prazosin binds the same receptor and blocks it.", "reading": [{"src": "Katzung 16e, Ch. 2", "sec": "Receptors mediate the actions of agonists and antagonists", "t": "An agonist binds the receptor and activates it, so the receptor signals as a direct result of the binding."}, {"src": "Katzung 16e, Ch. 6", "sec": "Autonomic Receptors, Table 6-2", "t": "α1 receptors sit on effector cells, especially smooth muscle; ligand binding forms IP3 and DAG and raises intracellular calcium, which contracts the muscle."}], "fg": "classes"},
{"id": "DL1-020", "lecture": "DL1", "prof": "Gottlieb", "tier": "new", "topic": "DL1", "skill": "drug", "source": "slide", "cite": "Exam_1_Drug_List_2026.pdf, Table 1", "sub": "gaba", "concept": "moa-diazepam", "tags": ["drug-list"], "stem": "Which drug acts as an allosteric agonist at the GABA receptor?", "options": [{"t": "Diazepam", "correct": true, "why": "Diazepam is listed as GABA receptor allosteric agonist."}, {"t": "Loratadine", "correct": false, "why": "Loratadine is listed as histamine H1 inverse agonist."}, {"t": "Varenicline", "correct": false, "why": "Varenicline is listed as nicotinic (Nn) partial agonist."}, {"t": "Tropicamide", "correct": false, "why": "Tropicamide is listed as muscarinic (M1, M2, M3) antagonist, reversible."}, {"t": "Metoprolol", "correct": false, "why": "Metoprolol is listed as β1 antagonist, reversible."}], "teach": "Diazepam does not bind where GABA binds. It binds a second site on the same GABA receptor, and while it sits there the receptor responds more strongly to GABA. Alone it does little; with GABA present it makes GABA work better.", "reading": [{"src": "Katzung 16e, Ch. 2", "sec": "Competitive & Irreversible Antagonists — allosteric modulators", "t": "Diazepam and the other benzodiazepines bind an allosteric site, not the site GABA binds, and increase the channel opening that GABA produces; on their own they have little effect."}], "note": "Two names for one mechanism. The Exam 1 drug list calls diazepam a GABA receptor allosteric agonist. Katzung Ch. 2 calls it a positive allosteric modulator: it binds a second site on the receptor, does little by itself, and makes the receptor respond more strongly to GABA. On the exam, use the drug list’s name.", "fg": "classes"},
{"id": "DL1-021", "lecture": "DL1", "prof": "Gottlieb", "tier": "new", "topic": "DL1", "skill": "drug", "source": "slide", "cite": "Exam_1_Drug_List_2026.pdf, Table 1", "sub": "adr", "concept": "moa-metoprolol", "tags": ["drug-list"], "stem": "Which drug is a reversible β1 antagonist?", "options": [{"t": "Metoprolol", "correct": true, "why": "Metoprolol is listed as β1 antagonist, reversible."}, {"t": "Pindolol", "correct": false, "why": "Pindolol is listed as β1 and β2 partial agonist."}, {"t": "Albuterol", "correct": false, "why": "Albuterol is listed as β2 partial agonist."}, {"t": "Prazosin", "correct": false, "why": "Prazosin is listed as α1 antagonist, reversible."}, {"t": "Phenoxybenzamine", "correct": false, "why": "Phenoxybenzamine is listed as α1 and α2 antagonist, irreversible."}], "teach": "Metoprolol binds β1 without activating it and blocks agonists there reversibly. Pindolol acts at β1 too, but as a partial agonist and at β2 as well.", "reading": [{"src": "Katzung 16e, Ch. 2", "sec": "Competitive & Irreversible Antagonists", "t": "A reversible (competitive) antagonist binds the receptor without activating it and blocks the agonist; enough agonist can surmount the block, so the agonist curve shifts right with the same maximum."}, {"src": "Katzung 16e, Ch. 6", "sec": "Autonomic Receptors, Table 6-2", "t": "β1 receptors sit especially on the heart; ligand binding stimulates adenylyl cyclase and raises cAMP, which speeds the sinoatrial node and increases contractility."}]},
{"id": "DL1-022", "lecture": "DL1", "prof": "Gottlieb", "tier": "new", "topic": "DL1", "skill": "drug", "source": "slide", "cite": "Exam_1_Drug_List_2026.pdf, Table 1", "sub": "chol", "concept": "moa-tropicamide", "tags": ["drug-list"], "stem": "Which drug is a reversible antagonist at muscarinic M1, M2 and M3 receptors?", "options": [{"t": "Tropicamide", "correct": true, "why": "Tropicamide is listed as muscarinic (M1, M2, M3) antagonist, reversible."}, {"t": "Acetylcholine", "correct": false, "why": "Acetylcholine is listed as muscarinic (M1, M2, M3) and nicotinic (Nn, Nm) agonist."}, {"t": "Varenicline", "correct": false, "why": "Varenicline is listed as nicotinic (Nn) partial agonist."}, {"t": "Diphenhydramine", "correct": false, "why": "Diphenhydramine is listed as non-selective histamine receptor antagonist."}, {"t": "Prazosin", "correct": false, "why": "Prazosin is listed as α1 antagonist, reversible."}], "teach": "Tropicamide binds M1, M2 and M3 without activating them and blocks acetylcholine there; the block is reversible.", "reading": [{"src": "Katzung 16e, Ch. 2", "sec": "Competitive & Irreversible Antagonists", "t": "A reversible (competitive) antagonist binds the receptor without activating it and blocks the agonist; enough agonist can surmount the block, so the agonist curve shifts right with the same maximum."}, {"src": "Katzung 16e, Ch. 6", "sec": "Autonomic Receptors, Table 6-2", "t": "M1 and M3 receptors signal through IP3, DAG and calcium; M2 receptors open potassium channels and inhibit adenylyl cyclase (myocardium)."}]},
{"id": "DL1-023", "lecture": "DL1", "prof": "Gottlieb", "tier": "new", "topic": "DL1", "skill": "drug", "source": "slide", "cite": "Exam_1_Drug_List_2026.pdf, Table 1", "sub": "gen", "concept": "partial-agonists", "tags": ["drug-list", "list"], "multi": true, "stem": "Which drugs on the Exam 1 list are partial agonists? Select all that apply.", "options": [{"t": "Albuterol", "correct": true, "why": "Albuterol is listed as β2 partial agonist."}, {"t": "Varenicline", "correct": true, "why": "Varenicline is listed as nicotinic (Nn) partial agonist."}, {"t": "Pindolol", "correct": true, "why": "Pindolol is listed as β1 and β2 partial agonist."}, {"t": "Metoprolol", "correct": false, "why": "Metoprolol is listed as β1 antagonist, reversible."}, {"t": "Loratadine", "correct": false, "why": "Loratadine is listed as histamine H1 inverse agonist."}, {"t": "Phenylephrine", "correct": false, "why": "Phenylephrine is listed as α1 agonist."}], "teach": "Three drugs on the list are partial agonists: albuterol (β2), varenicline (Nn) and pindolol (β1 and β2). Loratadine is an inverse agonist, metoprolol an antagonist, phenylephrine a full α1 agonist.", "reading": [{"src": "Katzung 16e, Ch. 2", "sec": "Partial Agonists", "t": "A partial agonist activates the receptor but produces a lower maximal response at full receptor occupancy than a full agonist does, and it competes with a full agonist for the same sites."}]},
{"id": "DL1-024", "lecture": "DL1", "prof": "Gottlieb", "tier": "new", "topic": "DL1", "skill": "drug", "source": "slide", "cite": "Exam_1_Drug_List_2026.pdf, Table 1", "sub": "adr", "concept": "alpha1-drugs", "tags": ["drug-list", "list"], "multi": true, "stem": "Which drugs on the Exam 1 list act at the α1 receptor? Select all that apply.", "options": [{"t": "Norepinephrine", "correct": true, "why": "Norepinephrine is listed as α1, α2, β1 and β2 agonist."}, {"t": "Prazosin", "correct": true, "why": "Prazosin is listed as α1 antagonist, reversible."}, {"t": "Phenylephrine", "correct": true, "why": "Phenylephrine is listed as α1 agonist."}, {"t": "Phenoxybenzamine", "correct": true, "why": "Phenoxybenzamine is listed as α1 and α2 antagonist, irreversible."}, {"t": "Metoprolol", "correct": false, "why": "Metoprolol is listed as β1 antagonist, reversible."}, {"t": "Albuterol", "correct": false, "why": "Albuterol is listed as β2 partial agonist."}], "teach": "Five rows name α1: norepinephrine and epinephrine (agonists at α1, α2, β1, β2), phenylephrine (α1 agonist), prazosin (α1 antagonist) and phenoxybenzamine (α1 and α2 antagonist, irreversible). Metoprolol and albuterol act at β receptors only."},
{"id": "DL1-025", "lecture": "DL1", "prof": "Gottlieb", "tier": "new", "topic": "DL1", "skill": "drug", "source": "slide", "cite": "Exam_1_Drug_List_2026.pdf, Table 1", "sub": "gen", "concept": "antagonists-list", "tags": ["drug-list", "list"], "multi": true, "stem": "Which drugs on the Exam 1 list are antagonists? Select all that apply.", "options": [{"t": "Tropicamide", "correct": true, "why": "Tropicamide is listed as muscarinic (M1, M2, M3) antagonist, reversible."}, {"t": "Prazosin", "correct": true, "why": "Prazosin is listed as α1 antagonist, reversible."}, {"t": "Metoprolol", "correct": true, "why": "Metoprolol is listed as β1 antagonist, reversible."}, {"t": "Diphenhydramine", "correct": true, "why": "Diphenhydramine is listed as non-selective histamine receptor antagonist."}, {"t": "Loratadine", "correct": false, "why": "Loratadine is listed as histamine H1 inverse agonist."}, {"t": "Pindolol", "correct": false, "why": "Pindolol is listed as β1 and β2 partial agonist."}, {"t": "Diazepam", "correct": false, "why": "Diazepam is listed as GABA receptor allosteric agonist."}], "teach": "The antagonists on the list are tropicamide, prazosin, phenoxybenzamine, metoprolol and diphenhydramine. Loratadine is classed as an inverse agonist, pindolol as a partial agonist and diazepam as an allosteric agonist.", "reading": [{"src": "Katzung 16e, Ch. 2", "sec": "Competitive & Irreversible Antagonists", "t": "A reversible (competitive) antagonist binds the receptor without activating it and blocks the agonist; enough agonist can surmount the block, so the agonist curve shifts right with the same maximum."}]},
{"id": "DL1-026", "lecture": "DL1", "prof": "Gottlieb", "tier": "new", "topic": "DL1", "skill": "drug", "source": "slide", "cite": "Exam_1_Drug_List_2026.pdf, Table 1", "sub": "hist", "concept": "histamine-drugs", "tags": ["drug-list", "list"], "multi": true, "stem": "Which drugs on the Exam 1 list act at histamine receptors? Select all that apply.", "options": [{"t": "Histamine", "correct": true, "why": "Histamine is listed as histamine H1 and H2 agonist."}, {"t": "Loratadine", "correct": true, "why": "Loratadine is listed as histamine H1 inverse agonist."}, {"t": "Diphenhydramine", "correct": true, "why": "Diphenhydramine is listed as non-selective histamine receptor antagonist."}, {"t": "Tropicamide", "correct": false, "why": "Tropicamide is listed as muscarinic (M1, M2, M3) antagonist, reversible."}, {"t": "Diazepam", "correct": false, "why": "Diazepam is listed as GABA receptor allosteric agonist."}, {"t": "Varenicline", "correct": false, "why": "Varenicline is listed as nicotinic (Nn) partial agonist."}], "teach": "Histamine (H1 and H2 agonist), loratadine (H1 inverse agonist) and diphenhydramine (non-selective histamine receptor antagonist) are the histamine-receptor drugs on the list."},
{"id": "DL1-027", "lecture": "DL1", "prof": "Gottlieb", "tier": "new", "topic": "DL1", "skill": "drug", "source": "slide", "cite": "Exam_1_Drug_List_2026.pdf, Table 1", "sub": "adr", "concept": "beta-drugs", "tags": ["drug-list", "list"], "multi": true, "stem": "Which drugs on the Exam 1 list act at β2 receptors? Select all that apply.", "options": [{"t": "Epinephrine", "correct": true, "why": "Epinephrine is listed as α1, α2, β1 and β2 agonist."}, {"t": "Albuterol", "correct": true, "why": "Albuterol is listed as β2 partial agonist."}, {"t": "Pindolol", "correct": true, "why": "Pindolol is listed as β1 and β2 partial agonist."}, {"t": "Metoprolol", "correct": false, "why": "Metoprolol is listed as β1 antagonist, reversible."}, {"t": "Phenylephrine", "correct": false, "why": "Phenylephrine is listed as α1 agonist."}, {"t": "Prazosin", "correct": false, "why": "Prazosin is listed as α1 antagonist, reversible."}], "teach": "β2 appears in the rows for norepinephrine, epinephrine, albuterol and pindolol. Metoprolol is β1 only; phenylephrine and prazosin act at α1."}
);
